  &reftitle.examples;

   Exemplo de untaint


<?php
$id = "42";
taint($id);
if (preg_match('/^\d+$/', $id)) {
    // estritamente validado como dígitos: seguro para confiar
    untaint($id);
}
var_dump(is_tainted($id));
?>


   &example.outputs.similar;


bool(false)

&reftitle.notes;


  Somente valores do tipo string podem ter a marca; passar um valor de
  outro tipo não tem efeito.
